<!doctype html>
<html lang="id">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="csrf-token" content="{{ csrf_token() }}">
    <title>{{ $toko->nama_toko }} — Katalog ERPlay AI</title>
    <meta name="description" content="Lihat katalog {{ $toko->nama_toko }}, cek harga dan stok langsung dengan bantuan ERPlay AI.">
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500;700&display=swap" rel="stylesheet">
    <style>
        :root{--primary:#0f172a;--accent:#3b82f6;--bg:#f8fafc;--surface:#fff;--text:#1e293b;--muted:#64748b;--border:#e2e8f0;--success:#10b981;--warning:#f59e0b;--danger:#ef4444;--r-sm:8px;--r-md:12px;--r-lg:16px;--shadow:0 12px 32px rgba(15,23,42,.12)}
        *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,sans-serif}button,input,select{font:inherit}.catalog-header{position:sticky;top:0;z-index:10;background:var(--primary);color:#fff}.header-inner,.container{width:min(1180px,calc(100% - 32px));margin:auto}.header-inner{min-height:64px;display:flex;align-items:center;gap:18px}.store-mark{display:flex;align-items:center;gap:10px;min-width:0}.store-mark img,.store-mark .logo-fallback{width:38px;height:38px;border-radius:50%;object-fit:cover;background:#fff;color:var(--primary);display:grid;place-items:center;font-weight:800}.store-name{font-size:18px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.store-slogan{font-size:12px;color:#cbd5e1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.share-btn{margin-left:auto;background:transparent;color:#fff;border:1px solid #64748b;border-radius:var(--r-sm);padding:9px 13px;cursor:pointer}.hero{padding:54px 0 34px;background:linear-gradient(135deg,#eff6ff 0%,#f8fafc 58%,#ecfeff 100%)}.eyebrow{color:var(--accent);font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.hero h1{font-size:clamp(28px,5vw,44px);line-height:1.08;letter-spacing:-.04em;margin:10px 0 12px;color:var(--primary);max-width:680px}.hero p{margin:0;color:var(--muted);max-width:610px;line-height:1.7}.toolbar{display:flex;gap:12px;align-items:center;margin:28px 0 16px;flex-wrap:wrap}.search{flex:1;min-width:230px;height:48px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-sm);padding:0 16px;outline:0}.search:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(59,130,246,.15)}.category{height:48px;border:1px solid var(--border);border-radius:var(--r-sm);background:#fff;padding:0 12px;color:var(--text)}.chips{display:flex;gap:8px;overflow:auto;padding-bottom:4px}.chip{border:1px solid var(--border);background:var(--surface);color:var(--muted);border-radius:18px;padding:8px 14px;white-space:nowrap;cursor:pointer}.chip.active{background:var(--accent);border-color:var(--accent);color:#fff}.catalog-main{padding:28px 0 100px}.result-meta{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;color:var(--muted);font-size:13px}.product-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.product-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:16px;transition:.2s}.product-card:hover{box-shadow:0 5px 15px rgba(15,23,42,.08);transform:translateY(-2px)}.product-image{aspect-ratio:1;background:#f1f5f9;border-radius:var(--r-sm);display:grid;place-items:center;overflow:hidden;margin-bottom:14px}.product-image img{width:100%;height:100%;object-fit:cover}.product-image span{font-size:30px;color:#94a3b8}.product-category{font-size:11px;color:var(--muted);margin-bottom:5px}.product-name{font-size:16px;line-height:1.35;margin:0 0 9px;min-height:43px}.price{font:700 18px 'JetBrains Mono',monospace;color:var(--accent);margin-bottom:10px}.stock{display:inline-flex;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:700}.stock-Tersedia{background:#d1fae5;color:#047857}.stock-Menipis{background:#fef3c7;color:#b45309}.stock-Habis{background:#fee2e2;color:#b91c1c}.empty{grid-column:1/-1;text-align:center;padding:70px 20px;color:var(--muted)}.empty strong{display:block;color:var(--text);font-size:18px;margin-bottom:5px}.chat-toggle{position:fixed;right:24px;bottom:24px;border:0;border-radius:999px;background:var(--accent);color:#fff;padding:14px 18px;box-shadow:var(--shadow);font-weight:700;cursor:pointer;z-index:20}.chat-panel{position:fixed;right:24px;bottom:82px;width:380px;height:520px;max-height:calc(100vh - 110px);background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);box-shadow:var(--shadow);display:none;flex-direction:column;overflow:hidden;z-index:20}.chat-panel.open{display:flex}.chat-head{background:var(--accent);color:#fff;padding:15px 16px;display:flex;align-items:center;justify-content:space-between}.chat-head strong{display:block}.chat-head small{opacity:.8}.chat-close{border:0;background:transparent;color:#fff;font-size:20px;cursor:pointer}.chat-body{padding:14px;overflow:auto;flex:1;background:var(--bg)}.bubble{max-width:84%;padding:10px 12px;border-radius:12px;margin-bottom:10px;font-size:13px;line-height:1.55;white-space:pre-wrap}.bubble.ai{background:var(--accent);color:#fff;border-bottom-left-radius:4px}.bubble.user{background:var(--primary);color:#fff;margin-left:auto;border-bottom-right-radius:4px}.chat-form{display:flex;gap:8px;border-top:1px solid var(--border);padding:10px;background:#fff}.chat-input{min-width:0;flex:1;border:1px solid var(--border);border-radius:var(--r-sm);padding:10px;outline:0}.chat-send{border:0;background:var(--accent);color:#fff;border-radius:var(--r-sm);padding:0 14px;cursor:pointer}.contact{color:var(--muted);font-size:13px;margin-top:18px}.contact a{color:var(--accent);font-weight:700}.loading{opacity:.6}@media(max-width:900px){.product-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:640px){.header-inner,.container{width:min(100% - 24px,1180px)}.store-name{font-size:15px}.store-slogan{display:none}.hero{padding:38px 0 24px}.product-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.product-card{padding:12px}.product-name{font-size:14px;min-height:38px}.price{font-size:14px}.chat-panel{right:12px;bottom:80px;width:calc(100% - 24px);height:min(520px,calc(100vh - 100px))}.chat-toggle{right:16px;bottom:16px}.category{width:100%}}
        /* Compact catalog presentation: keep search and products above the fold. */
        .hero{padding:28px 0 22px}.hero h1{font-size:clamp(24px,4vw,34px);margin:6px 0 8px}.hero p{font-size:14px;line-height:1.5}.contact{font-size:12px;margin-top:10px}.toolbar{margin:20px 0 12px}.catalog-main{padding-top:18px}.chips{display:none!important}.product-grid{gap:14px}.product-card{padding:13px}.product-name{font-size:14px;min-height:36px}.price{font-size:16px;margin-bottom:8px}.stock{padding:4px 8px;font-size:10px}@media(max-width:640px){.hero{padding:22px 0 18px}.product-card{padding:10px}.product-name{font-size:13px;min-height:34px}.price{font-size:14px}}
    </style>
</head>
<body>
<header class="catalog-header"><div class="header-inner"><div class="store-mark">@if($toko->logo)<img src="{{ asset('storage/' . $toko->logo) }}" alt="Logo {{ $toko->nama_toko }}">@else<div class="logo-fallback">{{ strtoupper(substr($toko->nama_toko,0,1)) }}</div>@endif<div><div class="store-name">{{ $toko->nama_toko }}</div><div class="store-slogan">{{ $toko->slogan_struk ?: 'Katalog resmi ERPlay AI' }}</div></div></div><button class="share-btn" id="shareBtn" type="button">↗ Bagikan</button></div></header>
<section class="hero"><div class="container"><div class="eyebrow">{{ $toko->catalog_hero_badge }}</div><h1>{{ $toko->catalog_hero_title }}</h1><p>{{ $toko->catalog_hero_description ?: 'Lihat produk, cek harga, dan tanyakan ketersediaan langsung ke ' . $assistantName . '.' }}</p><div class="contact">{{ $toko->alamat }} · <a href="tel:{{ $toko->no_telepon }}">{{ $toko->no_telepon }}</a>@if($toko->whatsapp_enabled && $toko->whatsapp_number) · <a href="https://wa.me/{{ preg_replace('/[^0-9]/', '', $toko->whatsapp_number) }}" target="_blank" rel="noopener">WhatsApp</a>@endif</div></div></section>
<main class="catalog-main"><div class="container"><div class="toolbar"><input class="search" id="searchInput" type="search" placeholder="Cari produk atau barcode..." aria-label="Cari produk"><select class="category" id="categorySelect" aria-label="Filter kategori"><option value="">Semua kategori</option>@foreach($categories as $category)<option value="{{ $category->id }}">{{ $category->nama_kategori }}</option>@endforeach</select></div><div class="chips" id="chips"><button class="chip active" data-category="" type="button">Semua</button>@foreach($categories as $category)<button class="chip" data-category="{{ $category->id }}" type="button">{{ $category->nama_kategori }}</button>@endforeach</div><div class="result-meta"><span id="resultMeta">Memuat katalog...</span><span>Harga jual umum</span></div><div class="product-grid" id="productGrid"></div></div></main>
<button class="chat-toggle" id="chatToggle" type="button" aria-label="Buka chat {{ $assistantName }}">✦ Tanya AI</button><section class="chat-panel" id="chatPanel" aria-label="Chat {{ $assistantName }}"><header class="chat-head"><div><strong>{{ $assistantName }}</strong><small>Lihat katalog toko, tanya harga/stok langsung ke AI.</small></div><button class="chat-close" id="chatClose" type="button" aria-label="Tutup chat">×</button></header><div class="chat-body" id="chatBody"><div class="bubble ai">Halo! Saya {{ $assistantName }}. Ada yang ingin Anda ketahui tentang produk atau toko ini?</div></div><form class="chat-form" id="chatForm"><input class="chat-input" id="chatInput" maxlength="500" placeholder="Tanya harga atau stok..." autocomplete="off"><button class="chat-send" type="submit">Kirim</button></form></section>
<script>
const productsUrl=@json($productsUrl), chatUrl=@json($chatUrl), csrf=document.querySelector('meta[name="csrf-token"]').content;let category='';let history=[];const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const grid=document.getElementById('productGrid'), meta=document.getElementById('resultMeta');
const money=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value);
function renderProducts(items){if(!items.length){grid.innerHTML='<div class="empty"><strong>Produk tidak ditemukan</strong><span>Coba kata kunci atau kategori lain.</span></div>';return}grid.innerHTML=items.map(p=>`<article class="product-card"><div class="product-image">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy">`:'<span>▦</span>'}</div><div class="product-category">${esc(p.category||'Produk')}</div><h2 class="product-name">${esc(p.name)}</h2><div class="price">${money(p.price)}</div><span class="stock stock-${esc(p.stock)}">${esc(p.stock)}</span></article>`).join('')}
async function loadProducts(){grid.classList.add('loading');const params=new URLSearchParams();const q=document.getElementById('searchInput').value.trim();if(q)params.set('query',q);if(category)params.set('category',category);try{const data=await fetch(`${productsUrl}?${params}`).then(r=>r.json());renderProducts(data.data||[]);meta.textContent=`${data.total||0} produk ditemukan`;}finally{grid.classList.remove('loading')}}
let timer;document.getElementById('searchInput').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(loadProducts,250)});document.getElementById('categorySelect').addEventListener('change',e=>{category=e.target.value;document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('active',c.dataset.category===category));loadProducts()});document.getElementById('chips').addEventListener('click',e=>{if(!e.target.matches('.chip'))return;category=e.target.dataset.category;document.getElementById('categorySelect').value=category;document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('active',c===e.target));loadProducts()});loadProducts();
const panel=document.getElementById('chatPanel');document.getElementById('chatToggle').onclick=()=>panel.classList.add('open');document.getElementById('chatClose').onclick=()=>panel.classList.remove('open');function bubble(text,type){const el=document.createElement('div');el.className=`bubble ${type}`;el.textContent=text;document.getElementById('chatBody').appendChild(el);document.getElementById('chatBody').scrollTop=99999}document.getElementById('chatForm').addEventListener('submit',async e=>{e.preventDefault();const input=document.getElementById('chatInput'),message=input.value.trim();if(!message)return;input.value='';bubble(message,'user');history.push({role:'user',content:message});const pending=document.createElement('div');pending.className='bubble ai loading';pending.textContent='Sedang mencari informasi...';document.getElementById('chatBody').appendChild(pending);try{const data=await fetch(chatUrl,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({message,history:history.slice(-8)})}).then(r=>r.json());pending.remove();bubble(data.reply||'Maaf, belum ada jawaban.','ai');history.push({role:'assistant',content:data.reply||''})}catch(error){pending.remove();bubble('Maaf, koneksi sedang bermasalah. Silakan hubungi toko secara langsung.','ai')}});document.getElementById('shareBtn').onclick=async()=>{try{await navigator.share({title:document.title,url:location.href})}catch{await navigator.clipboard?.writeText(location.href);alert('Link katalog berhasil disalin.')}};
</script>
</body></html>
